                            const phase = (evt && evt.phase) ? evt.phase : 'opd';
                            if (Number.isFinite(p)) onProgress({ percent: Math.max(0, Math.min(80, p * 0.8)), phase, message: msg });
                            else onProgress({ percent: null, phase, message: msg });
