                        const ix = Number.isInteger(c?.ix) ? c.ix : null;
                        const iy = Number.isInteger(c?.iy) ? c.iy : null;
                        if (ix === null || iy === null) continue;
                        if (ix < 0 || ix >= s || iy < 0 || iy >= s) continue;
