            opacity: 0,
            color: [pricedMinLog, pricedMaxLog],
            cmin: pricedMinLog,
            cmax: pricedMaxLog,
            colorscale: PRICE_COLORSCALE,
            showscale: true,
            colorbar: {
              title: 'price (log)',
              tickmode: 'array',
              tickvals: tickVals,
              ticktext: tickText,
            },
